def chain_follows_chain(chain):
    chain = list(chain)
    chain.sort()
    result = []
    for i in range(len(chain)):
        result.append(chain[i])
        if i == len(chain) - 1:
            break
        if i + 1 == len(chain):
            break
        result.append(chain[i + 1])
    return ','.join(result)

